// Google Sheets cells cannot hold arrays: join them into readable strings.
return $input.all().map(({ json }) => ({
  json: {
    ip: json.ip,
    found: json.found,
    ports: (json.ports || []).join(', '),
    services: (json.services || []).map((s) => `${s.port}/${s.name ?? 'unknown'}`).join(', '),
    vulnCount: json.vulnCount ?? (json.vulns || []).length,
    vulns: (json.vulns || []).join(', '),
    tags: (json.tags || []).join(', '),
    hostnames: (json.hostnames || []).join(', '),
    hasEolProduct: json.hasEolProduct ?? false,
    lookedUpAt: json.lookedUpAt ?? new Date().toISOString(),
  },
}));

// Build one plain-text summary of all looked-up IPs for the email.
const hosts = $input.all().map((item) => item.json);
const withData = hosts.filter((h) => h.found);
const lines = hosts.map((h) => {
  if (!h.found) return `${h.ip}: no data in InternetDB`;
  const ports = (h.services || []).map((s) => `${s.port}${s.name ? ` (${s.name})` : ''}`).join(', ') || 'none';
  const cves = h.vulnCount ?? (h.vulns || []).length;
  const eol = h.hasEolProduct ? ' [EOL product]' : '';
  return `${h.ip}: ports ${ports}; ${cves} known CVE(s)${eol}`;
});
const totalCves = withData.reduce((sum, h) => sum + (h.vulnCount ?? 0), 0);
return [{
  json: {
    subject: `Weekly exposure report: ${withData.length} of ${hosts.length} IPs exposed, ${totalCves} CVEs`,
    body: [
      'Shodan InternetDB weekly exposure report',
      '',
      ...lines,
      '',
      'InternetDB data refreshes about once a week and is free for non-commercial use.',
    ].join('\n'),
  },
}];
